/**
 * The contract ordinal of each step: how many quotes precede it.
 *
 * Every step currently advances the ordinal. Only quote steps should — the
 * claim tests will drive that out, and this is the single place to fix it.
 */
const contractOrdinals = (steps: Step[]): number[] =>
  steps.map((_step, index) => index);

export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => ({
  results: contractOrdinals(steps).map((ordinal, index) =>
    runStep(steps[index], { customer, ordinal }),
  ),
});

