/**
 * The contract ordinal of a step: how many quotes precede it.
 *
 * Every step currently advances the ordinal, so the ordinal is just the step
 * index. Only quote steps should advance it — the claim tests will drive that
 * out, and this is the single place to fix it.
 */
const contractOrdinalOf = (_steps: Step[], index: number): number => index;

export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => ({
  results: steps.map((step, index) =>
    runStep(step, { customer, ordinal: contractOrdinalOf(steps, index) }),
  ),
});
